def shortestBridge(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    start = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                start = (r, c)
                break
        if start:
            break
    seen[start[0]][start[1]] = True
    stack = [start]
    frontier = []
    while stack:
        y, x = stack.pop()
        frontier.append((y, x))
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and not seen[ny][nx]:
                seen[ny][nx] = True
                stack.append((ny, nx))
    flips = 0
    while frontier:
        nxt = []
        for y, x in frontier:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < rows and 0 <= nx < cols and not seen[ny][nx]:
                    if grid[ny][nx] == 1:
                        return flips
                    seen[ny][nx] = True
                    nxt.append((ny, nx))
        frontier = nxt
        flips += 1
    return -1
